/*
 * The protobuf runtime, as a module.
 *
 * `meshtastic-static.js` is generated by pbjs and expects to import the
 * protobuf runtime. The runtime we ship is the vendored `protobuf.min.js`,
 * which is a classic script and puts itself on `window`. This hands that
 * same object to the generated module.
 *
 * Only the reader, the writer and the small utilities are used from it.
 * The parts that compile code at run time are never reached, because the
 * generated module carries its own encoders and decoders. See
 * AGENTS.md 9.17.
 */

if (!window.protobuf) {
  throw new Error('protobuf.min.js must load before protobuf-runtime.js');
}

export default window.protobuf;
